// Generated by esquadro: do not edit. The list's text search: it searches
// as people type (after a pause), keeps the text in the URL without filling
// the history, clears with its button or Esc, and is reached with "/".
import { Search, X } from "lucide-react"
import { createContext, useContext, useEffect, useRef, useState } from "react"
import type { ReactNode } from "react"
import { Input } from "@/components/ui/input"
import { Spinner } from "@/components/ui/spinner"
import { t } from "./i18n.ts"

/** How long typing pauses before the list is searched. */
export const SEARCH_DELAY = 300

export function SearchBox({
  value,
  onSearch,
  busy,
  placeholder,
}: {
  value: string
  onSearch: (q: string) => void
  busy?: boolean
  placeholder?: string
}) {
  const [text, setText] = useState(value)
  const input = useRef<HTMLInputElement>(null)
  // The URL changed (Back, a link, clearing filters): the box follows it.
  useEffect(() => setText(value), [value])
  // After a pause in typing, search.
  useEffect(() => {
    const q = text.trim()
    if (q === value) return
    const timer = setTimeout(() => onSearch(q), SEARCH_DELAY)
    return () => clearTimeout(timer)
  }, [text])
  // "/" anywhere but in a field: to the search.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement
      if (e.key !== "/" || e.metaKey || e.ctrlKey || el.closest("input, textarea, select, [contenteditable=true]")) return
      e.preventDefault()
      input.current?.focus()
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [])
  const clear = () => {
    setText("")
    onSearch("")
    input.current?.focus()
  }
  return (
    <div className="relative w-full sm:w-72">
      <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
      <Input
        ref={input}
        type="search"
        className="pr-14 pl-8 [&::-webkit-search-cancel-button]:hidden"
        placeholder={placeholder ?? t("search")}
        value={text}
        onChange={(e) => setText(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter") onSearch(text.trim())
          if (e.key === "Escape" && text) {
            e.preventDefault()
            clear()
          }
        }}
        aria-label={placeholder ?? t("search")}
      />
      <div className="absolute top-1/2 right-2 flex -translate-y-1/2 items-center gap-1">
        {busy && text && <Spinner className="size-3.5 text-muted-foreground" />}
        {text ? (
          <button
            type="button"
            onClick={clear}
            className="rounded-sm p-0.5 text-muted-foreground hover:bg-muted hover:text-foreground"
            aria-label={t("clearSearch")}
          >
            <X className="size-3.5" />
          </button>
        ) : (
          <kbd className="pointer-events-none hidden h-5 items-center rounded border bg-muted px-1.5 font-mono text-[10px] text-muted-foreground sm:inline-flex">
            /
          </kbd>
        )}
      </div>
    </div>
  )
}

/** The text searched, for the cells to show where it is. */
export const SearchContext = createContext("")

/** A text with the words searched marked in it. */
export function Highlight({ text }: { text: string }): ReactNode {
  const q = useContext(SearchContext)
  const words = q
    .split(/\s+/)
    .filter((w) => w.length > 1)
    .map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))
  if (words.length === 0) return text
  const parts = text.split(new RegExp(`(${words.join("|")})`, "gi"))
  return parts.map((part, i) =>
    i % 2 === 1 ? (
      <mark key={i} className="rounded-sm bg-yellow-200/70 px-0.5 text-inherit dark:bg-yellow-500/30">
        {part}
      </mark>
    ) : (
      part
    ),
  )
}
